using System;
using System.Collections.Generic;
namespace LWS.TruckPoker {
public enum PokerStreet {Preflop,Flop,Turn,River,Showdown,Award}
public enum PokerAction {Fold,CheckCall,RaiseTo}
// This is the entire policy boundary. It contains no engine, deck, opponent hand, or future RNG state.
public sealed class PokerView {
 public readonly int Seat,Button,Actor,SmallBlind,BigBlind,Call,MinimumRaiseTo,MaximumRaiseTo,Pot,HandNumber,OwnA,OwnB;
 public readonly bool CanRaise; public readonly string RaiseReason;public readonly PokerStreet Street;
 public readonly int[] Board,Stacks,Bets,Contributions;public readonly bool[] Folded,InHand;
 internal PokerView(PokerTable table,int seat){Seat=seat;Button=table.Button;Actor=table.Actor;SmallBlind=table.SmallBlind;BigBlind=table.BigBlind;Call=Math.Min(table.Stack(seat),Math.Max(0,table.CurrentBet-table.Bet(seat)));MinimumRaiseTo=table.MinimumRaise;MaximumRaiseTo=table.Bet(seat)+table.Stack(seat);CanRaise=table.RaiseAllowed(seat,out string reason);RaiseReason=reason;Pot=table.Pot;HandNumber=table.HandNumber;Street=table.Street;Board=table.PublicBoard;Stacks=new int[table.Count];Bets=new int[table.Count];Contributions=new int[table.Count];Folded=new bool[table.Count];InHand=new bool[table.Count];for(int i=0;i<table.Count;i++){Stacks[i]=table.Stack(i);Bets[i]=table.Bet(i);Contributions[i]=table.Contribution(i);Folded[i]=table.IsFolded(i);InHand[i]=table.IsInHand(i);}int[] hand=table.OwnHand(seat);OwnA=hand[0];OwnB=hand[1];}
}
public sealed class PokerTable {
 readonly int[] stacks,bets,contributions,lastActedBet;readonly bool[] folded,inHand,acted;readonly int[,] hands;readonly int[] deck=new int[52],board=new int[5];readonly Random shuffle;readonly List<string> history=new List<string>();int revealMask;int cursor,boardCount,baseSmallBlind,handsPerLevel,previousBigBlind=-1;readonly int initialChips;
 public int Count=>stacks.Length;public int HandNumber{get;private set;}public int Button{get;private set;}=-1;public int SmallBlindSeat{get;private set;}public int BigBlindSeat{get;private set;}public int SmallBlind{get;private set;}public int BigBlind=>SmallBlind*2;public int Actor{get;private set;}=-1;public int CurrentBet{get;private set;}public int LastFullRaise{get;private set;}public PokerStreet Street{get;private set;}=PokerStreet.Award;public int Winner{get;private set;}=-1;public bool HandDone=>Street==PokerStreet.Award;public int[] PublicBoard{get{var result=new int[boardCount];Array.Copy(board,result,boardCount);return result;}}public IReadOnlyList<string> History=>history;public PokerPotAward[] Awards{get;private set;}=Array.Empty<PokerPotAward>();public int[] Returns{get;private set;}public int[] LastPayout{get;private set;}public bool Showdown{get;private set;}
 public int MinimumRaise=>CurrentBet==0?BigBlind:checked(CurrentBet+LastFullRaise);
 public int Pot{get{int result=0;foreach(int v in contributions)result+=v;return result;}}
 public PokerTable(int[] initialStacks,int randomSeed,int smallBlind=10,int levelHands=6){if(initialStacks==null||initialStacks.Length<2||initialStacks.Length>8||smallBlind<1||levelHands<1)throw new ArgumentException("Invalid tournament");stacks=(int[])initialStacks.Clone();foreach(int value in stacks){if(value<1)throw new ArgumentException("Each seat needs chips");initialChips=checked(initialChips+value);}int n=Count;bets=new int[n];contributions=new int[n];lastActedBet=new int[n];folded=new bool[n];inHand=new bool[n];acted=new bool[n];hands=new int[n,2];Returns=new int[n];LastPayout=new int[n];shuffle=new Random(randomSeed);baseSmallBlind=smallBlind;handsPerLevel=levelHands;}
 public int Stack(int seat)=>stacks[seat];public int Bet(int seat)=>bets[seat];public int Contribution(int seat)=>contributions[seat];public bool IsFolded(int seat)=>folded[seat];public bool IsInHand(int seat)=>inHand[seat];public int[] OwnHand(int seat)=>new[]{inHand[seat]?hands[seat,0]:-1,inHand[seat]?hands[seat,1]:-1};public bool PubliclyRevealed(int seat)=>Showdown&&(revealMask&(1<<seat))!=0;
 public PokerView View(int seat){if(seat<0||seat>=Count)throw new ArgumentOutOfRangeException(nameof(seat));return new PokerView(this,seat);}
 int Next(int from,Func<int,bool> predicate){for(int d=1;d<=Count;d++){int i=(from+d+Count)%Count;if(predicate(i))return i;}return -1;}
 int LiveCount(){int result=0;for(int i=0;i<Count;i++)if(inHand[i]&&!folded[i])result++;return result;}
 int CanActCount(){int result=0;for(int i=0;i<Count;i++)if(inHand[i]&&!folded[i]&&stacks[i]>0)result++;return result;}
 bool CanAct(int i)=>inHand[i]&&!folded[i]&&stacks[i]>0;
 bool NeedsAction(int i)=>CanAct(i)&&(!acted[i]||bets[i]<CurrentBet);
 void AddHistory(string value){history.Add(value);if(history.Count>18)history.RemoveAt(0);}
 public bool BeginHand(){if(!HandDone)throw new InvalidOperationException("Current hand is live");int remaining=0;for(int i=0;i<Count;i++)if(stacks[i]>0){remaining++;Winner=i;}if(remaining==1){Actor=-1;return false;}Winner=-1;int next=Next(Button,i=>stacks[i]>0);if(remaining==2&&HandNumber>0&&Next(next,i=>stacks[i]>0)==previousBigBlind)next=Next(next,i=>stacks[i]>0);Button=next;HandNumber++;SmallBlind=Math.Min(Math.Max(1,initialChips/4),(int)Math.Min(int.MaxValue,(long)baseSmallBlind*(1L<<Math.Min(18,(HandNumber-1)/handsPerLevel))));
  Array.Clear(bets,0,Count);Array.Clear(contributions,0,Count);Array.Clear(acted,0,Count);Array.Clear(lastActedBet,0,Count);Array.Clear(Returns,0,Count);Array.Clear(LastPayout,0,Count);Awards=Array.Empty<PokerPotAward>();history.Clear();Showdown=false;revealMask=0;boardCount=cursor=0;for(int i=0;i<Count;i++){inHand[i]=stacks[i]>0;folded[i]=!inHand[i];hands[i,0]=hands[i,1]=-1;}for(int i=0;i<52;i++)deck[i]=i;for(int i=51;i>0;i--){int k=shuffle.Next(i+1);int value=deck[i];deck[i]=deck[k];deck[k]=value;}
  SmallBlindSeat=remaining==2?Button:Next(Button,i=>inHand[i]);BigBlindSeat=Next(SmallBlindSeat,i=>inHand[i]);previousBigBlind=BigBlindSeat;for(int card=0;card<2;card++){int seat=Button;for(int j=0;j<remaining;j++){seat=Next(seat,i=>inHand[i]);hands[seat,card]=deck[cursor++];}}Pay(SmallBlindSeat,SmallBlind);Pay(BigBlindSeat,BigBlind);CurrentBet=LastFullRaise=BigBlind;Street=PokerStreet.Preflop;AddHistory("BLINDS "+SmallBlind+" / "+BigBlind);Actor=Next(BigBlindSeat,CanAct);Advance(BigBlindSeat,false);CheckChips();return true;
 }
 void Pay(int seat,int amount){amount=Math.Min(amount,stacks[seat]);stacks[seat]-=amount;bets[seat]+=amount;contributions[seat]+=amount;}
 public bool RaiseAllowed(int seat,out string reason){reason="";if(HandDone||seat!=Actor||!CanAct(seat)){reason="Wait for your turn";return false;}if(bets[seat]+stacks[seat]<=CurrentBet){reason="Stack covers a call only";return false;}if(CanActCount()<2){reason="No opponent can contest a raise";return false;}if(acted[seat]&&CurrentBet-lastActedBet[seat]<LastFullRaise){reason="Short all-in did not reopen raising";return false;}return true;}
 public bool Act(int seat,PokerAction action,int raiseTo,out string reason){reason="";if(HandDone||seat!=Actor||!CanAct(seat)){reason="Not this seat's action";return false;}int old=CurrentBet;
  if(action==PokerAction.Fold){folded[seat]=true;AddHistory("P"+(seat+1)+" FOLDS");}
  else if(action==PokerAction.CheckCall){int amount=Math.Min(stacks[seat],Math.Max(0,CurrentBet-bets[seat]));Pay(seat,amount);AddHistory("P"+(seat+1)+(amount==0?" CHECKS":" CALLS "+amount)+(stacks[seat]==0?" · ALL IN":""));}
  else if(action==PokerAction.RaiseTo){if(!RaiseAllowed(seat,out reason))return false;int maximum=bets[seat]+stacks[seat];if(raiseTo<=CurrentBet||raiseTo>maximum){reason="Raise exceeds stack or does not raise";return false;}if(raiseTo<MinimumRaise&&raiseTo!=maximum){reason="Minimum total is "+MinimumRaise;return false;}Pay(seat,raiseTo-bets[seat]);CurrentBet=raiseTo;int increment=CurrentBet-old;if(increment>=LastFullRaise)LastFullRaise=increment;AddHistory("P"+(seat+1)+(old==0?" BETS ":" RAISES TO ")+CurrentBet+(stacks[seat]==0?" · ALL IN":""));}
  else{reason="Unknown action";return false;}acted[seat]=true;lastActedBet[seat]=CurrentBet;Advance(seat,true);CheckChips();return true;
 }
 void RefundStreet(){int owner=-1,highest=0,second=0;for(int i=0;i<Count;i++)if(bets[i]>highest){second=highest;highest=bets[i];owner=i;}else second=Math.Max(second,bets[i]);if(owner>=0&&highest>second){int value=highest-second;bets[owner]-=value;contributions[owner]-=value;stacks[owner]+=value;Returns[owner]+=value;AddHistory("P"+(owner+1)+" UNCALLED "+value+" RETURNED");}}
 void Advance(int from,bool didAct){if(LiveCount()==1){Award(false);return;}int canAct=CanActCount();if(canAct>1){int next=Next(from,NeedsAction);if(next>=0){Actor=next;return;}}else if(canAct==1){int actual=0;foreach(int bet in bets)actual=Math.Max(actual,bet);CurrentBet=Math.Min(CurrentBet,actual);int only=Next(-1,CanAct);if(bets[only]<CurrentBet){Actor=only;return;}}
  RefundStreet();if(Street==PokerStreet.River){Award(true);return;}bool runout=CanActCount()<2;do{cursor++; // burn one card per street
   if(Street==PokerStreet.Preflop){Street=PokerStreet.Flop;for(int i=0;i<3;i++)board[boardCount++]=deck[cursor++];}
   else{Street=Street==PokerStreet.Flop?PokerStreet.Turn:PokerStreet.River;board[boardCount++]=deck[cursor++];}
   Array.Clear(bets,0,Count);Array.Clear(acted,0,Count);Array.Clear(lastActedBet,0,Count);CurrentBet=0;LastFullRaise=BigBlind;AddHistory(Street.ToString().ToUpperInvariant());if(!runout){Actor=Next(Button,CanAct);return;}
  }while(Street!=PokerStreet.River);Award(true);
 }
 void Award(bool showdown){bool allIn=false;for(int i=0;i<Count;i++)if(inHand[i]&&!folded[i]&&stacks[i]==0)allIn=true;Showdown=showdown;Street=PokerStreet.Showdown;long[] ranks=new long[Count];bool[] dead=new bool[Count];for(int i=0;i<Count;i++){dead[i]=!inHand[i]||folded[i];if(dead[i])continue;if(showdown){int[] seven=new int[7];seven[0]=hands[i,0];seven[1]=hands[i,1];Array.Copy(board,0,seven,2,5);ranks[i]=PokerHand.Evaluate(seven);}else ranks[i]=1;}
  int[] returned;PokerPotAward[] awards;var payout=PokerPots.Settle(contributions,dead,ranks,Button,out returned,out awards);Awards=awards;revealMask=0;if(showdown){if(allIn){for(int i=0;i<Count;i++)if(inHand[i]&&!folded[i])revealMask|=1<<i;}else foreach(var potAward in awards)foreach(int winner in potAward.Winners)revealMask|=1<<winner;}for(int i=0;i<Count;i++){stacks[i]+=payout[i];LastPayout[i]=payout[i];Returns[i]+=returned[i];}Array.Clear(contributions,0,Count);Array.Clear(bets,0,Count);Actor=-1;CurrentBet=0;Street=PokerStreet.Award;AddHistory(showdown?"SHOWDOWN · POTS AWARDED":"LAST LIVE HAND WINS");CheckChips();int remaining=0;for(int i=0;i<Count;i++)if(stacks[i]>0){remaining++;Winner=i;}if(remaining!=1)Winner=-1;
 }
 public void CheckChips(){int count=Pot;foreach(int value in stacks){if(value<0)throw new InvalidOperationException("Negative stack");count=checked(count+value);}if(count!=initialChips)throw new InvalidOperationException("Chip conservation failed");}
}
}
